(()=>{
 const previous=EmberViewport.prototype.render;
 EmberViewport.prototype.render=function(particles,settings,grid,light){
  const T=Ember3D;this.flipbookBuckets||=new Map();for(const bucket of this.flipbookBuckets.values())bucket.count=0;
  for(const p of particles){const s=p.settings||settings,f=s.flipbook;if(!f||s.renderer==='mesh')continue;const key=f.image+':'+!!(s.glow&&!s.anime);let bucket=this.flipbookBuckets.get(key);if(!bucket){const geometry=new T.PlaneGeometry(1,1);for(const [name,size]of [['particleCenter',3],['particleShape',4],['particleTint',4],['atlasShape',4]])geometry.setAttribute(name,new T.InstancedBufferAttribute(new Float32Array(this.max*size),size));const texture=new T.TextureLoader().load(f.image);texture.colorSpace=T.SRGBColorSpace;const material=new T.ShaderMaterial({uniforms:{atlas:{value:texture}},transparent:true,depthWrite:false,blending:s.glow&&!s.anime?T.AdditiveBlending:T.NormalBlending,side:T.DoubleSide,vertexShader:`attribute vec3 particleCenter;attribute vec4 particleShape;attribute vec4 particleTint;attribute vec4 atlasShape;varying vec2 atlasUV;varying vec4 shade;varying vec2 anime;void main(){vec2 q=position.xy*particleShape.x;float angle=particleShape.y;q=mat2(cos(angle),-sin(angle),sin(angle),cos(angle))*q;vec4 center=modelViewMatrix*vec4(particleCenter,1.0);center.xy+=q;gl_Position=projectionMatrix*center;float col=mod(atlasShape.z,atlasShape.x),row=floor(atlasShape.z/atlasShape.x);atlasUV=vec2((uv.x+col)/atlasShape.x,(uv.y+atlasShape.y-1.0-row)/atlasShape.y);shade=particleTint;anime=vec2(particleShape.z,particleShape.w);}`,fragmentShader:`uniform sampler2D atlas;varying vec2 atlasUV;varying vec4 shade;varying vec2 anime;void main(){vec4 texel=texture2D(atlas,atlasUV);if(anime.x>.5){float l=max(max(texel.r,texel.g),texel.b);if(l>0.0001)texel.rgb*=((floor(min(l,.9999)*anime.y)/(anime.y-1.0))/l);}gl_FragColor=texel*shade;if(gl_FragColor.a<.001)discard;\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}`});bucket=new T.InstancedMesh(geometry,material,this.max);bucket.count=0;bucket.frustumCulled=false;this.scene.add(bucket);this.flipbookBuckets.set(key,bucket);}
   const i=bucket.count;if(i>=this.max)continue;const t=p.age/p.life,color=new T.Color(EmberAnimation.particleColor(s,t)),brightness=s.glow?3:1,radius=p.size*(s.size/(p.birthSize||s.size))*EmberLifetime.size(s,t)*2;bucket.geometry.attributes.particleCenter.array.set([p.x,p.y,p.z],i*3);bucket.geometry.attributes.particleShape.array.set([radius,p.rotation||0,s.anime?1:0,s.animeSteps??3],i*4);bucket.geometry.attributes.particleTint.array.set([color.r*brightness,color.g*brightness,color.b*brightness,EmberLifetime.opacity(s,t)*(s.opacity??1)],i*4);bucket.geometry.attributes.atlasShape.array.set([f.columns,f.rows,EmberFlipbook.frame(f,p.age),0],i*4);bucket.count++;
  }
  for(const [key,bucket]of this.flipbookBuckets){bucket.visible=bucket.count>0;for(const a of Object.values(bucket.geometry.attributes))if(a.isInstancedBufferAttribute)a.needsUpdate=true;if(!bucket.count){bucket.geometry.dispose();bucket.material.uniforms.atlas.value.dispose();bucket.material.dispose();this.scene.remove(bucket);this.flipbookBuckets.delete(key);}}
  previous.call(this,particles,settings,grid,light);
 };
})();
